class Solution {
  public boolean checkEquivalence(Node root1, Node root2) {
    // with only '+', two trees are equal exactly when they use the same multiset of variables
    int[] count = new int[26];
    tally(root1, count, 1);
    tally(root2, count, -1);
    for (int c : count) if (c != 0) return false;
    return true;
  }

  private void tally(Node node, int[] count, int sign) {
    if (node == null) return;
    if (node.val != '+') count[node.val - 'a'] += sign;
    tally(node.left, count, sign);
    tally(node.right, count, sign);
  }
}
